import numpy as np

def can_grow(L, s, max_steps=1000):
    r = L // 2
    grid = set()
    grid.add((0, 0))

    for step in range(max_steps):
        found = False
        for c in list(grid):
            neighborhood = []
            for dx in range(-r, r + 1):
                for dy in range(-r, r + 1):
                    if (c[0] + dx, c[1] + dy) not in grid:
                        neighborhood.append((c[0] + dx, c[1] + dy))

            if len(neighborhood) >= s:
                for i in range(s):
                    grid.add(neighborhood[i])
                found = True
                break
        if not found:
            break

    return len(grid)

for s in range(20, 50):
    print(f"L=7, s={s}, final_size={can_grow(7, s)}")

