import random

def can_grow_random(L, s, threshold=500, attempts=5):
    r = L // 2
    for attempt in range(attempts):
        grid = set()
        grid.add((0, 0))
        for _ in range(1000):
            # Pick a random green cell
            c = random.choice(list(grid))
            neighborhood = []
            for dx in range(-r, r + 1):
                for dy in range(-r, r + 1):
                    if (c[0] + dx, c[1] + dy) not in grid:
                        neighborhood.append((c[0] + dx, c[1] + dy))
            if len(neighborhood) >= s:
                # Pick s random neighbors
                for cell in random.sample(neighborhood, s):
                    grid.add(cell)
            if len(grid) > threshold:
                return True
    return False

print(f"L=7, s=33, grows={can_grow_random(7, 33)}")
